Требования:
1. Создать ~/nixos-config/home/whitepeach.nix:
   ```nix
   { config, pkgs, lib, ... }: {
     home.username = "whitepeach";
     home.homeDirectory = "/home/whitepeach";
     home.stateVersion = "26.05";

     dconf.settings = {
       "org/gnome/shell" = {
         disable-user-extensions = false;
         enabled-extensions = [
           "appindicatorsupport@rgcjonas.gmail.com"
           "dash-to-dock@micxgx.gmail.com"
           "blur-my-shell@aunetx"
           "caffeine@patapon.info"
           "tophat@fflewddur.github.io"
         ];
       };
       "org/gnome/desktop/input-sources" = {
         sources = [
           (lib.gvariant.mkTuple [ "xkb" "us" ])
           (lib.gvariant.mkTuple [ "xkb" "ru" ])
         ];
         xkb-options = [ "grp:shift_alt_toggle" ];
       };
       "org/gnome/desktop/interface" = {
         cursor-theme = "Bibata-Modern-Ice";
         cursor-size = lib.gvariant.mkInt32 24;
         enable-hot-corners = false;
       };
     };
   }
   ```

2. Обновить flake.nix — добавить home-manager.users.whitepeach

3. Обновить docs/config.md:
   - Файловая система: ext4 (не btrfs)
   - Группы kasiro: wheel, networkmanager (без video)
   - whitepeach-configuration.nix в ~/nixos-config/ (не /home/whitepeach/nixos-config/)
   - Удалить раздел о блокировке locks (удалены)
   - Удалить NIXPKGS_SUPPRESS_EVAL_WARNINGS

